{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Membership for steady habits</title>
  <meta name="description" content="Membership offering focused on tangible daily habits, outcomes and frameworks.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <svg class="logo" viewBox="0 0 100 30" aria-hidden="true"><rect width="100" height="30" rx="6" fill="#7FB77E"></rect><text x="50" y="20" font-size="12" text-anchor="middle" fill="#fff">{{BUSINESS_NAME}}</text></svg>
      <div class="tag">{{TAGLINE}}</div>
    </div>
    <nav class="main-nav">
      <a href="index.html">Begin</a>
      <a href="programs.html">Journeys</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Invest</a>
      <a href="testimonials.html">Praise</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Reach</a>
      <button class="try-btn" id="open-exercise">Try it now</button>
    </nav>
  </header>

  <main>
    <!-- Hero (split diagonal) -->
    <section class="hero split-diagonal">
      <div class="hero-left">
        <h1>Membership for reliable daily practices</h1>
        <p>Join a guided membership that turns intentions into steady habits through short frameworks you can repeat every morning.</p>
        <div class="hero-ctas">
          <a class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <button class="secondary" id="open-challenge">Generate 7-day challenge</button>
        </div>
        <ul class="hero-features">
          <li>Weekly micro-lessons</li>
          <li>Actionable habit templates</li>
          <li>Printable daily checklist</li>
        </ul>
      </div>
      <div class="hero-right">
        <svg class="pattern-embed" viewBox="0 0 200 200" aria-hidden="true">
          <defs>
            <pattern id="p" width="20" height="20" patternUnits="userSpaceOnUse">
              <rect width="10" height="10" fill="#E9F6EE"></rect>
              <rect x="10" y="10" width="10" height="10" fill="#F6FBF7"></rect>
            </pattern>
            <linearGradient id="g" x1="0" x2="1">
              <stop offset="0" stop-color="#CFEBD1"/>
              <stop offset="1" stop-color="#FFFFFF"/>
            </linearGradient>
          </defs>
          <rect width="100%" height="100%" fill="url(#p)"></rect>
          <circle cx="140" cy="60" r="30" fill="url(#g)" opacity="0.9"></circle>
        </svg>
        <div class="hero-card">
          <h3>Starter sequence</h3>
          <ol>
            <li>One-minute settle</li>
            <li>Two intentional breaths</li>
            <li>Micro-journal prompt</li>
          </ol>
          <a class="card-cta" href="programs.html">Explore Journeys</a>
        </div>
      </div>
    </section>

    <!-- Gallery -->
    <section class="gallery" id="gallery">
      <h2>Scenes from the practice</h2>
      <div class="grid">
        <figure><svg viewBox="0 0 100 60"><rect width="100" height="60" fill="#F1F8F4"/></svg><figcaption>Short guided sessions</figcaption></figure>
        <figure><svg viewBox="0 0 100 60"><rect width="100" height="60" fill="#E9F6EE"/></svg><figcaption>Printable checklists</figcaption></figure>
        <figure><svg viewBox="0 0 100 60"><rect width="100" height="60" fill="#F6FBF7"/></svg><figcaption>Weekly frameworks</figcaption></figure>
      </div>
    </section>

    <!-- What to expect -->
    <section class="expectations">
      <h2>What to expect inside the membership</h2>
      <ul>
        <li><strong>Outcome-driven cycles:</strong> monthly focuses with measurable trackers.</li>
        <li><strong>Habit blueprints:</strong> short templates for morning, pause and evening rituals.</li>
        <li><strong>Community workshops:</strong> cohort calls to practice together once a month.</li>
      </ul>
    </section>

    <!-- Objections / FAQ -->
    <section class="faq">
      <h2>Questions you might have</h2>
      <details>
        <summary>Is this a medical program?</summary>
        <p>No. This membership focuses on habits, outcomes and frameworks, not medical advice.</p>
      </details>
      <details>
        <summary>How much time will it take?</summary>
        <p>Most frameworks are designed to take 3–12 minutes. Consistency is prioritized over length.</p>
      </details>
      <details>
        <summary>Can I print checklists?</summary>
        <p>Yes. Use the 7-day challenge generator to get a printable checklist you can post at home.</p>
      </details>
    </section>

    <!-- CTA / Membership -->
    <section class="membership-cta">
      <h2>Membership access</h2>
      <p>Ongoing cycles, habit blueprints, and monthly practical workshops. Pay monthly or claim an introductory plan.</p>
      <div class="pricing-snippet">
        <div class="price"><span class="amount">$29</span><span class="term">/month</span></div>
        <a class="primary-cta" href="pricing.html">See membership details</a>
      </div>
    </section>

    <!-- Habit builder area (hidden until used) -->
    <section class="habit-builder" id="habit-builder" aria-hidden="true">
      <h2>7-Day Challenge Generator</h2>
      <form id="challenge-form">
        <label>Habit name<input type="text" id="habit-name" placeholder="e.g., Morning pages"></label>
        <label>Intensity
          <select id="habit-intensity">
            <option value="low">Low — 2–5 min</option>
            <option value="med">Medium — 6–12 min</option>
            <option value="high">High — 15+ min</option>
          </select>
        </label>
        <label>Start day<input type="date" id="start-date"></label>
        <div class="form-actions">
          <button type="button" id="generate-challenge">Create checklist</button>
          <button type="button" id="print-challenge">Print checklist</button>
        </div>
      </form>
      <div id="challenge-output" class="challenge-output" aria-live="polite"></div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="contact">
      <div>{{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
      <div>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
    <div class="small">Membership support &middot; <a href="privacy.html">Privacy</a></div>
  </footer>

  <!-- Modal for guided exercise -->
  <div id="exercise-modal" class="modal" aria-hidden="true">
    <div class="modal-panel">
      <button class="close" id="close-exercise">×</button>
      <h3 id="exercise-title">Try a short practice</h3>
      <div class="exercise-tabs">
        <button class="tab active" data-mode="breathing">Breathing</button>
        <button class="tab" data-mode="journaling">Journaling</button>
        <button class="tab" data-mode="intention">Intention</button>
      </div>
      <div class="exercise-content" id="exercise-content">
        <!-- Dynamic content injected by JS -->
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
